const body = $input.first().json.body || $input.first().json;
const toolCallList = body?.message?.toolCallList || [];
const toolCall = toolCallList[0] || {};
const toolCallId = toolCall.id || 'unknown';
let args = {};
try { args = JSON.parse(toolCall.function?.arguments || '{}'); } catch(e) { args = {}; }
return [{ json: { toolCallId, patientName: args.patientName || '', phone: args.phone || '', doctorName: args.doctorName || '', appointmentDate: args.appointmentDate || '', appointmentTime: args.appointmentTime || '', notes: args.notes || '' } }];

